package com.u1.slicer.bambu

import com.u1.slicer.slice.SlicerTarget
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.util.Base64
import java.util.zip.GZIPInputStream

/**
 * Exact machine G-code templates from the Bambu profiles bundled with the
 * embedded OrcaSlicer 2.2.4 engine. Keeping the templates engine-matched avoids
 * placeholders added by newer BambuStudio releases that this native core
 * cannot evaluate.
 */
internal object BambuSingleNozzleMachineGcode {
    private const val END_DIVIDER = "\n__U1_SLICER_BAMBU_END__\n"
    private const val CHANGE_DIVIDER = "\n__U1_SLICER_BAMBU_CHANGE__\n"
    // BambuStudio P2S 0.4 mm templates, pinned for the embedded Orca 2.2.4
    // engine and kept separate from every existing target's payload.
    private const val P2S_ENCODED = ""

    internal data class Templates(
        val start: String,
        val end: String,
        val changeFilament: String,
    )

    private val encodedByTarget = mapOf(
        SlicerTarget.BambuX1C to "",
        SlicerTarget.BambuX1E to "",
        SlicerTarget.BambuP1P to "",
        SlicerTarget.BambuP1S to "",
        SlicerTarget.BambuA1 to "",
    ).plus(SlicerTarget.BambuP2S to P2S_ENCODED)

    internal val sourceProfileByTarget = mapOf(
        SlicerTarget.BambuX1C to "Bambu Lab X1 Carbon 0.4 nozzle.json",
        SlicerTarget.BambuX1E to "Bambu Lab X1E 0.4 nozzle.json",
        SlicerTarget.BambuP1P to "Bambu Lab P1P 0.4 nozzle.json",
        SlicerTarget.BambuP1S to "Bambu Lab P1S 0.4 nozzle.json",
        SlicerTarget.BambuP2S to "Bambu Lab P2S 0.4 nozzle.json",
        SlicerTarget.BambuA1 to "Bambu Lab A1 0.4 nozzle.json",
    )

    private val templatesByTarget by lazy {
        encodedByTarget.mapValues { (target, encoded) ->
            val compressed = Base64.getDecoder().decode(encoded)
            val sourceText = GZIPInputStream(ByteArrayInputStream(compressed)).use { input ->
                val output = ByteArrayOutputStream()
                input.copyTo(output)
                output.toString(Charsets.UTF_8.name())
            }
            val text = sourceText.engineCompatibleFor(target)
            require(text.countOccurrences(END_DIVIDER) == 1) {
                "$target template payload must contain one end divider"
            }
            require(text.countOccurrences(CHANGE_DIVIDER) == 1) {
                "$target template payload must contain one change divider"
            }
            val start = text.substringBefore(END_DIVIDER)
            val remainder = text.substringAfter(END_DIVIDER)
            val end = remainder.substringBefore(CHANGE_DIVIDER)
            val change = remainder.substringAfter(CHANGE_DIVIDER)
            require(start.isNotBlank() && end.isNotBlank() && change.isNotBlank()) {
                "$target templates must not be blank"
            }
            Templates(start, end, change)
        }
    }

    fun forTarget(target: SlicerTarget): Templates =
        templatesByTarget[target]
            ?: error("No single-nozzle Bambu templates for $target")

    private fun String.countOccurrences(needle: String): Int =
        windowed(needle.length).count { it == needle }

    /**
     * BambuStudio's P2S macro uses the newer material glass-transition
     * placeholder. OrcaSlicer 2.2.4 cannot evaluate it, so retain the same
     * low-temperature chamber-cooling branch using the engine-supported first
     * layer bed-temperature proxy instead.
     */
    private fun String.engineCompatibleFor(target: SlicerTarget): String =
        if (target == SlicerTarget.BambuP2S) {
            replace(
                "{if (min_vitrification_temperature <= 50)}",
                "{if (bed_temperature_initial_layer_single <= 50)}",
            ).replace("initial_no_support_filament_id", "initial_extruder")
                .replace("initial_filament_id", "initial_extruder")
                .replace("current_filament_id", "current_extruder")
                .replace("next_filament_id", "next_extruder")
                // The newer P2S material profile subtracts this per-filament
                // pre-tower cooling offset. Orca 2.2.4 has no matching
                // setting, so retain the established direct target
                // temperature used by the engine-compatible macro.
                .replace(
                    "new_filament_temp - filament_cooling_before_tower[next_extruder]",
                    "new_filament_temp",
                )
                // Orca 2.2.4 supports max() but not ceil(). Preserve at
                // least the P2S flush synchronisation time, with up to five
                // extra seconds rather than rounding it down.
                .replace(
                    "SYNC T{ceil(flush_length / 80) * 5}",
                    "SYNC T{max(flush_length / 16 + 5, 5)}",
                )
                // BambuStudio maps a logical filament through a nested
                // array before selecting this per-extruder retraction value.
                // The embedded engine accepts the direct equivalent only.
                .replace(
                    "retract_length_toolchange[filament_map[next_extruder]-1]",
                    "retract_length_toolchange[next_extruder]",
                )
                // P2S's newer per-filament auxiliary-fan transition block
                // references material options introduced after Orca 2.2.4.
                // It is an optional cooling refinement, so omit the complete
                // block rather than substitute unverified fan speeds.
                .replace(
                    Regex(
                        "\\{if \\(overall_chamber_temperature < 40\\)\\}.*?M623\\n\\n;not set fan changing filament",
                        RegexOption.DOT_MATCHES_ALL,
                    ),
                    "; P2S per-filament auxiliary fan transition omitted: unsupported OrcaSlicer 2.2.4 material options\n;not set fan changing filament",
                )
                .replace("initial_nozzle_id", "initial_extruder")
                .replace("current_nozzle_id", "current_extruder")
                .replace("next_nozzle_id", "next_extruder")
                .replace("nozzle_diameter_at_nozzle_id", "nozzle_diameter")
                .replace("max_print_z", "max_layer_z")
                .replace("flush_volumetric_speeds", "filament_max_volumetric_speed")
                .replace("flush_temperatures", "nozzle_temperature_range_high")
                .replace("first_layer_temperature", "nozzle_temperature_initial_layer")
                // This P2S-only flat-print chamber hold is not configurable
                // in Orca 2.2.4. Select the macro's normal/legacy branches.
                .replace(
                    "hold_chamber_temp_for_flat_print",
                    "(bed_temperature_initial_layer_single < 0)",
                )
                // This optional P2S obstacle scan depends on max_print_z,
                // introduced after Orca 2.2.4. Existing engine-matched
                // templates rely on the printer's normal preflight instead.
                .replace(
                    Regex("\\{if max_layer_z >= 145\\}.*?\\{endif\\}", RegexOption.DOT_MATCHES_ALL),
                    "; P2S obstacle scan omitted: max_print_z is unavailable in OrcaSlicer 2.2.4",
                )
        } else {
            this
        }
}
